/* Question bank: Parasitology · Protozoa and Antiparasitics.
   Written for the PHA3109 lecture "Microbiology - Parasitology" (11.18.2026).
   Every question follows docs/Question Writing Guidelines.docx: single best
   answer, positive stems, 4 parallel options, a rationale for every item.
   Clinical and pharmacology items follow the lecture and should be verified
   by faculty before release. */
var TOPIC_ID = "parasitology";
var TOPIC_TITLE = "Parasitology · Protozoa and Antiparasitics";

/* Checkpoint answers. `q` repeats the stem shown in parasitology.html so
   this file can be read on its own. */
var CHECKPOINTS = {
 /* m1s1 · Parasite classification */
 c1a: {q:"Protozoa and helminths look very different. Which feature do they share?",
  options:["Both are eukaryotes with a nucleus","Both are single-celled organisms","Both lack membrane-bound organelles","Both are classified as metazoa"], answer:0,
  why:"Protozoa (single-celled) and helminths (multicellular worms) are both eukaryotic. Only helminths are metazoa, and neither lacks a nucleus."},
 c1b: {q:"Which criterion is used to group the protozoa in this lecture?",
  options:["The type of worm","The site of infection","The Gram stain reaction","The shape of the cell wall"], answer:1,
  why:"Protozoa are grouped by where they infect: intestinal, urogenital, and blood/tissue. Helminths are grouped by type of worm."},
 c1c: {q:"Flatworms belong to which phylum?",
  options:["Nemathelminths","Protozoa","Platyhelminthes","Sporozoa"], answer:2,
  why:"Platyhelminthes are the flatworms. Nemathelminths are the roundworms. Both phyla are helminths (metazoa)."},

 /* m1s2 · Life-cycle forms */
 c2a: {q:"Which protozoan form is motile, metabolically active, feeding, and reproducing?",
  options:["Cyst","Oocyst","Hypnozoite","Trophozoite"], answer:3,
  why:"The trophozoite is the active form, surrounded by a flexible membrane. The cyst is the dormant, thick-walled transmission form."},
 c2b: {q:"Why is the cyst form important for fecal-oral transmission?",
  options:["Its thick wall lets it survive in the environment until it is swallowed","It multiplies in water before it is swallowed","Its flagella let it swim toward a new host","It penetrates intact skin during contact"], answer:0,
  why:"Cysts are nonmotile and nonreproducing, but their thick wall lets them survive outside the host in food and water."},
 c2c: {q:"Which term names the nonflagellated form of a protozoan such as Leishmania?",
  options:["Promastigote","Amastigote","Trypomastigote","Sporozoite"], answer:1,
  why:"Amastigotes lack a flagellum. Promastigotes and trypomastigotes are the flagellated forms of Leishmania and Trypanosoma."},

 /* m1s3 · Hosts and transmission */
 c3a: {q:"The sexual cycle of Plasmodium takes place in the mosquito. What does that make the mosquito?",
  options:["The intermediate host","The dead-end host","The definitive host","The accidental host"], answer:2,
  why:"The definitive host is the one in which the sexual cycle occurs. Humans, where the asexual cycle occurs, are the intermediate host."},
 c3b: {q:"Which link in the malaria chain of transmission does a bed net interrupt?",
  options:["Contact between the mosquito vector and the human host","Ingestion of cysts in contaminated water","Spread of the parasite during sexual contact","Inhalation of the parasite into the lungs"], answer:0,
  why:"Bed nets and repellents block the vector from biting. Water treatment, condoms, and avoiding inhalation interrupt other routes."},
 c3c: {q:"How are the intestinal protozoa transmitted?",
  options:["By the bite of an insect vector","By inhalation of airborne cysts","By penetration of intact skin","By ingestion of cysts (oocysts for Cryptosporidium)"], answer:3,
  why:"Entamoeba, Giardia, and Cryptosporidium are acquired by swallowing the transmission form in fecally contaminated food or water."},

 /* m2s1 · Entamoeba histolytica */
 c4a: {q:"Why is metronidazole alone insufficient to clear invasive amebiasis completely?",
  options:["It does not reach the liver","It acts on tissue trophozoites but leaves cysts in the colon lumen","It is inactivated by stomach acid","It kills cysts but not trophozoites"], answer:1,
  why:"Metronidazole or tinidazole treats tissue disease. A luminal agent (paromomycin or iodoquinol) then clears cysts that remain in the gut."},
 c4b: {q:"How do Entamoeba trophozoites travel from the colon to the liver?",
  options:["Through the lymphatic vessels","By crossing the diaphragm","Through the portal circulation","By ascending the bile ducts"], answer:2,
  why:"Trophozoites that invade the colon wall enter portal blood, which drains to the liver, where they form abscesses."},
 c4c: {q:"How many nuclei does a mature Entamoeba histolytica cyst contain?",
  options:["One","Two","Eight","Four"], answer:3,
  why:"The mature cyst has four nuclei, a feature used to recognize it on stool microscopy."},

 /* m2s2 · Giardia and Cryptosporidium */
 c5a: {q:"A hiker drank untreated stream water and now has weeks of foul-smelling, nonbloody diarrhea with fat malabsorption and no fever. Which organism is most likely?",
  options:["Giardia lamblia","Entamoeba histolytica","Cryptosporidium hominis","Trichomonas vaginalis"], answer:0,
  why:"Giardia attaches to the duodenal wall without invading. The inflammation causes malabsorption of fats and protein, with no fever and no blood."},
 c5b: {q:"Which stain reveals Cryptosporidium oocysts in a fecal smear?",
  options:["Modified Kinyoun acid-fast stain","India ink","Gram stain","Giemsa stain of a thick blood film"], answer:0,
  why:"On a modified acid-fast stain, oocysts appear red on a blue background. A stool antigen test is an alternative."},
 c5c: {q:"Why does cryptosporidiosis become severe in a patient with advanced HIV?",
  options:["The parasite invades the bloodstream","The parasite releases a potent toxin","The host cannot clear the infection, so diarrhea becomes prolonged and dehydrating","The oocysts spread to the liver"], answer:2,
  why:"In immunocompetent people the illness is self-limited. Without effective immunity it persists, causing malnutrition and dehydration. Antiretroviral therapy reduces oocyst shedding."},

 /* m2s3 · Trichomonas vaginalis */
 c6a: {q:"Why is partner treatment important even when the partner has no symptoms?",
  options:["The partner may later develop a cyst-stage infection","An untreated partner remains a reservoir and can reinfect the patient","Partner treatment prevents drug resistance","The partner will develop a liver abscess"], answer:1,
  why:"Most infections cause few or no symptoms, and the human genital tract is the reservoir. Treating one partner alone invites reinfection."},
 c6b: {q:"Which stage of Trichomonas vaginalis is transmitted between people?",
  options:["Cyst","Oocyst","Sporozoite","Trophozoite"], answer:3,
  why:"Trichomonas has a trophozoite form and no cyst form, so the trophozoite is passed by sexual contact."},
 c6c: {q:"Which test is the most sensitive for diagnosing trichomoniasis?",
  options:["Nucleic acid amplification test (NAAT)","Wet mount microscopy","Stool ova and parasite exam","Modified acid-fast stain"], answer:0,
  why:"NAAT is the most sensitive test. A wet mount misses many infections."},

 /* m2s4 · Diagnostic challenge and drug mechanisms */
 c7a: {q:"Which drug acts as a luminal agent by inhibiting protein synthesis?",
  options:["Metronidazole","Paromomycin","Nitazoxanide","Tinidazole"], answer:1,
  why:"Paromomycin binds 16S ribosomal RNA and inhibits protein synthesis. It clears cysts in the gut lumen after tissue treatment."},
 c7b: {q:"Which chemical group of metronidazole is reduced inside the parasite to form DNA-damaging radicals?",
  options:["The hydroxyl group","The methyl group","The nitro group","The imidazole nitrogen"], answer:2,
  why:"The nitro group (–NO2) is reduced inside the parasite, forming nitroso radicals that bind and break DNA strands."},
 c7c: {q:"In protozoa, nitazoxanide interferes with which enzyme?",
  options:["Dihydrofolate reductase","Cytochrome bc1","Dihydropteroate synthase","Pyruvate:ferredoxin oxidoreductase (PFOR)"], answer:3,
  why:"According to its drug label, nitazoxanide interferes with PFOR-dependent energy metabolism in protozoa."},

 /* m3s1 · Malaria life cycle */
 c8a: {q:"Why is the mosquito considered the definitive host of Plasmodium?",
  options:["The sexual cycle takes place in the mosquito","The mosquito is where the parasite causes disease","The mosquito carries the hypnozoites","The asexual red cell cycle takes place in the mosquito"], answer:0,
  why:"By definition, the definitive host is where the sexual cycle occurs. The asexual liver and red cell cycles occur in humans, the intermediate host."},
 c8b: {q:"Which parasite form does the female Anopheles mosquito inject into a human?",
  options:["Merozoites","Gametocytes","Sporozoites","Hypnozoites"], answer:2,
  why:"Sporozoites, the motile spore-like form, travel from the bite to the liver."},
 c8c: {q:"Which parasite form is released from the liver to invade red blood cells?",
  options:["Sporozoites","Merozoites","Oocysts","Hypnozoites"], answer:1,
  why:"Hepatic schizonts divide by fission into merozoites, the cells that parasitize red blood cells."},

 /* m3s2 · Five species */
 c9a: {q:"Which two species can relapse because of dormant liver stages?",
  options:["P. falciparum and P. malariae","P. knowlesi and P. falciparum","P. vivax and P. ovale","P. malariae and P. knowlesi"], answer:2,
  why:"P. vivax and P. ovale form hypnozoites that can reactivate months to years later."},
 c9b: {q:"A long-lasting malaria infection with a 3-day (quartan) fever cycle progresses to nephrotic syndrome. Which species fits best?",
  options:["P. malariae","P. vivax","P. knowlesi","P. ovale"], answer:0,
  why:"P. malariae has a quartan cycle, can persist for a long time, and chronic cases can cause nephrotic syndrome."},
 c9c: {q:"Which species is a zoonotic parasite of macaques in Southeast Asia, with a 24-hour cycle?",
  options:["P. ovale","P. falciparum","P. malariae","P. knowlesi"], answer:3,
  why:"P. knowlesi is a macaque parasite that can infect humans and become severe quickly."},

 /* m3s3 · Red cell destruction */
 c10a: {q:"Why can P. falciparum cause cerebral malaria and acute kidney injury?",
  options:["It forms hypnozoites in the brain and kidney","Parasitized red cells block capillaries, and extensive hemolysis injures the kidney","It releases a neurotoxin into the blood","It infects neurons and renal tubule cells directly"], answer:1,
  why:"Infected red cells occlude capillaries, causing hemorrhage and necrosis, including in the brain. Massive hemolysis leads to hemoglobinuria and renal failure."},
 c10b: {q:"In which two ways are red blood cells destroyed in malaria?",
  options:["Antibody lysis and complement fixation","Toxin release and clotting","Merozoite release and splenic trapping","Bone marrow failure and bleeding"], answer:2,
  why:"Red cells rupture when merozoites are released, and the spleen traps and lyses parasitized cells, which leads to splenomegaly."},
 c10c: {q:"Which inherited trait protects against severe falciparum malaria?",
  options:["Sickle cell heterozygosity","Hereditary hemochromatosis","Factor V Leiden","Cystic fibrosis carrier status"], answer:0,
  why:"People heterozygous for sickle cell are protected. G6PD deficiency is also protective. These are genetic, not immune, defenses."},

 /* m3s4 · Diagnosis */
 c11a: {q:"Which smear should be used to determine the percentage of infected red blood cells?",
  options:["Thick smear","Thin smear","Rapid diagnostic test","Stool smear"], answer:1,
  why:"The thin smear identifies the species and the percent of red cells infected. The thick smear is more sensitive for detecting parasites."},
 c11b: {q:"A febrile traveler's first blood smear is negative, but malaria is still suspected. What is the next step?",
  options:["Rule out malaria and look for another cause","Order a PCR and wait for the result before any further smears","Start primaquine empirically","Repeat smears every 12 to 24 hours for three sets"], answer:3,
  why:"One negative smear does not rule malaria out. Repeat blood films every 12 to 24 hours for a total of three sets."},
 c11c: {q:"Why should a positive rapid diagnostic test be followed by microscopy?",
  options:["The test cannot identify every species or measure parasitemia","The test detects antibodies from past infections","The test is less sensitive than PCR","The test result takes several days"], answer:0,
  why:"RDTs detect parasite antigens but cannot identify every species or measure the percent of infected cells, which guides treatment."},

 /* m4s1 · Drug targets */
 c12a: {q:"Why is a blood-stage drug alone insufficient to prevent relapse of P. vivax malaria?",
  options:["It does not reach red blood cells","It does not kill the hypnozoites in the liver","It acts on the mosquito stages","It increases the formation of gametocytes"], answer:1,
  why:"Blood-stage drugs clear the red cell infection, but dormant hypnozoites survive in the liver and can reactivate. An anti-relapse drug is needed."},
 c12b: {q:"Which drug targets liver hypnozoites?",
  options:["Chloroquine","Artesunate","Primaquine","Atovaquone"], answer:2,
  why:"Primaquine (and tafenoquine) kill hypnozoites. The others act on red cell stages."},
 c12c: {q:"Artemether-lumefantrine acts mainly on which stage of the parasite?",
  options:["Red blood cell (erythrocytic) stages","Liver hypnozoites","Sporozoites in the salivary gland","The sexual stages in the mosquito"], answer:0,
  why:"Both drugs in the combination act on the erythrocytic stages, which cause the symptoms of malaria."},

 /* m4s2 · Mechanisms */
 c13a: {q:"Which antimalarial mechanism interferes with the parasite's mitochondrial electron transport chain?",
  options:["Blocking hemozoin formation in the food vacuole","Activating an endoperoxide bridge with heme iron","Inhibiting dihydrofolate reductase","Inhibiting cytochrome bc1"], answer:3,
  why:"Atovaquone inhibits the cytochrome bc1 complex, which blocks electron transport and pyrimidine synthesis."},
 c13b: {q:"Chloroquine blocks hemozoin formation in the food vacuole. What is the consequence for the parasite?",
  options:["Toxic heme accumulates","Hemoglobin can no longer enter the vacuole","The vacuole becomes alkaline and the parasite divides faster","Its DNA strands break"], answer:0,
  why:"The parasite normally detoxifies heme by polymerizing it into hemozoin. When that step is blocked, free heme builds up and kills the parasite."},
 c13c: {q:"What activates the endoperoxide bridge of artemether and artesunate?",
  options:["Hepatic CYP3A4","Glutathione","Heme iron","Stomach acid"], answer:2,
  why:"Heme iron cleaves the endoperoxide bridge, generating free radicals that damage parasite heme and proteins."},

 /* m4s3 · G6PD */
 c14a: {q:"Why does G6PD deficiency increase the risk of hemolysis during primaquine treatment?",
  options:["Primaquine is metabolized faster in G6PD deficiency","Red cells make too little NADPH to regenerate glutathione, so oxidative damage goes unchecked","G6PD deficiency increases the number of hypnozoites","Primaquine binds G6PD and forms a toxic complex"], answer:1,
  why:"G6PD makes NADPH, which regenerates reduced glutathione, the red cell's antioxidant. Without it, the oxidative stress from primaquine damages red cells."},
 c14b: {q:"Which test is required before a patient receives tafenoquine?",
  options:["CD4 count","Liver function panel","HLA-B*5701 screen","Quantitative G6PD test"], answer:3,
  why:"A quantitative G6PD test is required first because tafenoquine, like primaquine, can cause hemolysis in G6PD deficiency."},
 c14c: {q:"Which product of the G6PD reaction is used to regenerate reduced glutathione?",
  options:["NADPH","ATP","NADH","FADH2"], answer:0,
  why:"G6PD generates NADPH in the pentose phosphate pathway. Glutathione reductase uses NADPH to regenerate reduced glutathione."},

 /* m4s4 · Treatment and prevention */
 c15a: {q:"Which therapeutic principle separates severe malaria treatment from uncomplicated malaria treatment?",
  options:["Severe malaria is treated with primaquine first","Severe malaria is treated with oral chloroquine at a higher dose","Severe malaria starts with IV artesunate, then a full oral regimen once parasitemia is 1% or less and oral drugs are tolerated","Severe malaria is treated with atovaquone-proguanil alone"], answer:2,
  why:"IV artesunate is first-line for severe malaria. A complete oral course follows once parasitemia is at or below 1% and the patient can take oral drugs."},
 c15b: {q:"Which regimen is the first-choice oral treatment for uncomplicated P. falciparum malaria?",
  options:["Chloroquine","Artemether-lumefantrine","Primaquine","IV artesunate"], answer:1,
  why:"Artemether-lumefantrine is the first choice. Atovaquone-proguanil is the second choice, and quinine plus doxycycline is an alternative."},
 c15c: {q:"A traveler returns from Haiti with uncomplicated P. falciparum malaria. Which drug is appropriate?",
  options:["Chloroquine","Primaquine alone","Spiramycin","Pyrimethamine"], answer:0,
  why:"Haiti is a chloroquine-sensitive area (with the Dominican Republic and Central America west of the Panama Canal), so chloroquine or hydroxychloroquine can be used."},

 /* m5s1 · Toxoplasma */
 c16a: {q:"Why can toxoplasmosis be more severe in an immunocompromised person than in a healthy adult?",
  options:["The parasite forms hypnozoites in these patients","Antibodies are the main defense and they are absent","Cell-mediated immunity normally limits tachyzoite spread, and that control is lost","The parasite becomes resistant to sulfadiazine"], answer:2,
  why:"Macrophages engulf the parasite and cell-mediated immunity limits tachyzoite spread. When that fails, disseminated disease such as encephalitis follows."},
 c16b: {q:"A pregnant woman cleans her new kitten's litter box. Which parasite form is she most likely to swallow?",
  options:["Tissue cysts","Oocysts shed in cat feces","Sporozoites from an insect bite","Trophozoites from contaminated water"], answer:1,
  why:"Cats shed oocysts in their feces. Tissue cysts are acquired from undercooked meat."},
 c16c: {q:"Why is leucovorin given with pyrimethamine and sulfadiazine?",
  options:["To protect the patient's cells from folate depletion","To increase the absorption of pyrimethamine","To kill tissue cysts in the brain","To prevent transmission to the fetus"], answer:0,
  why:"Leucovorin (folinic acid) can be used by human cells, which replaces the folate that the combination depletes, without rescuing the parasite."},

 /* m5s2 · Pneumocystis */
 c17a: {q:"Why is Pneumocystis pneumonia associated with impaired host defenses?",
  options:["The organism is acquired from blood transfusion","The organism produces a toxin that suppresses immunity","Intact host defenses keep the infection from causing pneumonia","The organism invades the bone marrow first"], answer:2,
  why:"Pneumonia arises when host defenses are diminished, as in HIV with a low CD4 count."},
 c17b: {q:"Which regimen is the first-choice treatment for Pneumocystis pneumonia?",
  options:["Trimethoprim-sulfamethoxazole","Fluconazole","Metronidazole","Chloroquine"], answer:0,
  why:"Trimethoprim-sulfamethoxazole is first choice. Pentamidine and atovaquone are alternatives. Pneumocystis is a fungus, but it is not treated with azoles."},
 c17c: {q:"When is adjunctive prednisone added to Pneumocystis pneumonia treatment?",
  options:["When the CD4 count is below 200 cells/µL","When the patient is also pregnant","When the chest film shows a cavity","When PaO2 is below 70 mm Hg or the A-a gradient is 35 mm Hg or higher"], answer:3,
  why:"Prednisone is added for severe hypoxemia. A CD4 count below 200 cells/µL is the threshold for prophylaxis, not for steroids."},

 /* m5s3 · Host defenses */
 c18a: {q:"How does sequential inhibition of folate metabolism differ from inhibition of a single enzyme?",
  options:["It targets two different pathways","It blocks two steps in the same pathway, so the combined effect is greater","It acts on human cells instead of the parasite","It works by stimulating the immune system"], answer:1,
  why:"A sulfonamide blocks dihydropteroate synthase and a DHFR inhibitor blocks a later step. Blocking two steps in a row is more effective than either alone."},
 c18b: {q:"Which enzyme does sulfadiazine inhibit?",
  options:["Dihydrofolate reductase","Thymidylate synthase","Dihydropteroate synthase","Pyruvate:ferredoxin oxidoreductase"], answer:2,
  why:"Sulfadiazine inhibits dihydropteroate synthase, blocking folate synthesis. Pyrimethamine inhibits dihydrofolate reductase."},
 c18c: {q:"A patient recovers from amebic dysentery and has antibodies against Entamoeba histolytica. What does the lecture teach about these antibodies?",
  options:["They do not prevent reinfection","They give lifelong protection","They cause the liver abscess","They block the formation of cysts"], answer:0,
  why:"Antibodies form in the host, but they do not prevent reinfection, so prevention depends on safe food and water."}
};

